		return Query{}, &QueryError{
			Op:     "BuildGetByID",
			Reason: "entity has empty Table",
		}
	}
	if entity.IDColumn == "" {
		return Query{}, &QueryError{
			Op:     "BuildGetByID",
			Reason: "entity has empty IDColumn",
		}
	}

