//	SELECT ... FROM customers WHERE "name" ILIKE ? AND "status" = ? AND "city" = ?
//	Args: ["%Ivan%", "active", "Moscow"]
func (b *Builder) BuildFilter(entity Entity, filterCols []string, filterVals []any, filterOps []string) (Query, error) {
