			// Меньше placeholder'ов, чем параметров — это программная
			// ошибка cq.SQL, защищаемся явно.
			return Query{}, &QueryError{
				Op:     "BuildCustomQuery",
				Reason: "placeholder count mismatch in SQL: fewer '?' than Params",
			}
		}
