		return Query{}, &QueryError{
			Op:     "BuildCustomQuery",
			Reason: "custom query must be a SELECT statement, got: " + summarizeSQL(cq.SQL),
		}
	}
	if len(args) != len(cq.Params) {
		return Query{}, &QueryError{
			Op:     "BuildCustomQuery",
			Reason: paramCountMismatchReason(len(cq.Params), len(args)),
		}
	}

