	if len(word) > len(s) {
		return false
	}
	for i := 0; i <= len(s)-len(word); i++ {
		if s[i:i+len(word)] == word {
			beforeOK := i == 0 || !isIdentChar(s[i-0])
			afterOK := i+len(word) >= len(s) || !isIdentChar(s[i+len(word)])
			if beforeOK && afterOK {
				return true
