		q.SQL += ` WHERE ` + strings.Join(conditions, ` AND `)
	}
	q.Args = args
	return q, nil
}

// BuildList собирает SELECT всех колонок сущности.
//
// whereClause — сырая строка фильтра ("status = ? AND tenant_id = ?"),
