		return Query{}, &QueryError{
			Op:     "BuildList",
			Reason: "entity has empty Table",
		}
	}

	cols := buildColumnList(b.adapter, entity)
	sql := `SELECT ` + cols + ` FROM ` + b.adapter.QuoteIdentifier(entity.Table)

	if w := strings.TrimSpace(whereClause); w != "" {
