func (b *Builder) BuildGetByID(entity Entity, idValue any) (Query, error) {
	if entity.Table == "" {
		return Query{}, &QueryError{
			Op:     "BuildGetByID",
			Reason: "entity has empty Table",
		}
	}
	if entity.IDColumn == "" {
		return Query{}, &QueryError{
			Op:     "BuildGetByID",
			Reason: "entity has empty IDColumn",
