		}, 10000)
		if err != nil {
			RespondError(w, http.StatusInternalServerError, "mapping_error", err.Error())
			return
		}

		setPaginationHeaders(w, total, limit, offset)
		RespondJSON(w, http.StatusOK, results)
	}
}

