	rows, err := db.QueryContext(context.Background(), countSQL, args...)
	if err != nil {
		return -1
	}
	defer rows.Close() //nolint:errcheck
	var total int
	if rows.Next() {
		_ = rows.Scan(&total)
	}
	return total
}

