//     INSERT, UPDATE, DELETE, DROP, ALTER, CREATE, TRUNCATE, EXEC, EXECUTE.
//
// Все проверки case-insensitive.
func isValidSelect(sql string) bool {
	s := strings.TrimSpace(sql)
	if s == "" {
		return false
	}

	// 1. Удаляем block comments /* ... */
	for {
		start := strings.Index(s, "/*")
		if start < 0 {
			break
