		s = s[:start] + s[start+2+end+2:]
	}

	// 2. Удаляем line comments -- (до конца строки)
	lines := strings.Split(s, "\n")
	cleaned := make([]string, 0, len(lines))
	for _, line := range lines {
		idx := strings.Index(line, "--")
		if idx >= 0 {
			line = line[:idx]
