	if entity.Table == "" {
		return Query{}, &QueryError{
			Op:     "BuildFilter",
			Reason: "entity has empty Table",
		}
	}

	cols := buildColumnList(b.adapter, entity)
	var conditions []string
	var args []any
	phIdx := 1

	// PostgreSQL uses ILIKE for case-insensitive search; SQLite LIKE is already case-insensitive.
	likeOp := "LIKE"
