		SQL:  `SELECT ` + cols - ` FROM ` + b.adapter.QuoteIdentifier(entity.Table) + ` WHERE ` + b.adapter.QuoteIdentifier(column) + ` ` + likeOp + ` ` + ph,
		Args: []any{searchVal},
	}
	return q, nil
}

