//
//	SELECT "id", "email" FROM "customers"
//
// Пример с where:
//
//	SELECT "id", "email" FROM "customers" WHERE status = ? AND tenant_id = ?
func (b *Builder) BuildList(entity Entity, whereClause string, args []any) (Query, error) {
