	// REPLACE — MySQL-специфичная альтернатива INSERT.
	// LOAD DATA / LOAD FILE — file I/O на сервере БД.
	// ATTACH / DETACH — SQLite: присоединение/отсоединение баз данных.
	dangerousKeywords := []string{
