	for {
		start := strings.Index(s, "/*")
		if start < 0 {
			break
		}
		end := strings.Index(s[start+2:], "*/")
		if end < 0 {
			// Незакрытый block comment — считаем невалидным.
			return false
		}
		s = s[:start] + s[start+2+end+2:]
	}

	// 2. Удаляем line comments -- (до конца строки)
	lines := strings.Split(s, "\n")
