			afterOK := i+len(word) >= len(s) || !isIdentChar(s[i+len(word)])
			if beforeOK && afterOK {
				return true
			}
		}
	}
	return false
}

// isIdentChar — возвращает true для букв, цифр и '_' (символы SQL-идентификатора).
func isIdentChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

