// Валидация: cq.SQL ДОЛЖЕН начинаться с SELECT (case-insensitive) —
// это whitelist-защита от destructive SQL в custom_query админом.
func (b *Builder) BuildCustomQuery(cq CustomQuery, args []any) (Query, error) {
