				continue
			}
			escaped := strings.NewReplacer("%", "\\%", "_", "\\_").Replace(s)
			args = append(args, "%"+escaped+"%")
			conditions = append(conditions, b.adapter.QuoteIdentifier(column)+" "+likeOp+" "+ph)
			phIdx++
		case "eq":
