		itoa(expected) + " params, got " + itoa(got)
}

// itoa — локальный strconv.Itoa, чтобы не тянуть strconv в hot-path.
// Используется только в сообщениях об ошибках.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := false
	if n < 0 {
		neg = true
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
