			phIdx++
		}
	}

	q := Query{SQL: `SELECT ` + cols + ` FROM ` + b.adapter.QuoteIdentifier(entity.Table)}
	if len(conditions) > 0 {
		q.SQL += ` WHERE ` + strings.Join(conditions, ` AND `)
	}
