func isIdentChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

// summarizeSQL — обрезает SQL до первых N символов для сообщения об ошибке.
