	// не из user input. В SQL это часть статической структуры запроса.
	q := Query{
		SQL:  `SELECT ` + cols + ` FROM ` + b.adapter.QuoteIdentifier(entity.Table) + ` WHERE ` + b.adapter.QuoteIdentifier(entity.IDColumn) + ` = ` + ph,
		Args: []any{idValue},
