		if !ok {
			continue // пропускаем неизвестные колонки
		}

		val := filterVals[i]
		op := filterOps[i]

		ph := b.adapter.TranslatePlaceholder(phIdx)

		switch op {
		case "like":
			// LIKE/ILIKE поиск с экранированием wildcards
			s, ok := val.(string)
			if !ok {
				continue
			}
			escaped := strings.NewReplacer("%", "\\%", "_", "\\_").Replace(s)
			args = append(args, "%"+escaped+"%")
