// filterVals — значения фильтров (порядок соответствует filterCols).
// filterOps  — типы операций: "like" для string, "eq" для чисел/bool.
//
// Пример:
//
//	filterCols: ["name", "status", "city"]
//	filterVals: ["Ivan", "active", "Moscow"]
//	filterOps:  ["like", "eq", "eq"]
//
